/**
 * UserResponse is a user account as admins see it.
 */
export interface UserResponse {
  id: number /* int64 */;
  username: string;
  role: string;
  createdAt: number /* int64 */;
  disabled: boolean;
  /**
   * TwoFactor is whether the user has TOTP or a passkey set up.
   */
  twoFactor: boolean;
}
/**
 * UsersResponse lists every user.
 */
export interface UsersResponse {
  users: UserResponse[];
}
/**
 * CreateUserRequest adds a user. Where 2FA is required, they set it up at
 * first sign-in.
 */
export interface CreateUserRequest {
  username: string;
  password: string;
  role: string;
}
/**
 * UpdateUserRequest changes a user. Missing fields are left as they are.
 */
export interface UpdateUserRequest {
  role?: string;
  disabled?: boolean;
}

